import {installNavigation} from './navigation.js';
import {aiAvailability,availabilityText} from './ai-availability.js';
const el=(tag,cls,text)=>{const n=document.createElement(tag);n.className=cls;if(text)n.textContent=text;return n;};
installNavigation();
const bar=el('aside','ai-availability'),title=el('strong',''),detail=el('small','');bar.setAttribute('aria-label','AI availability and daily allowance');bar.append(title,detail);document.querySelector('.watch-source-bar').after(bar);
const notice=el('p','crew-availability');notice.setAttribute('role','status');document.querySelector('.party-header').after(notice);let posts=[];
function update(s){bar.dataset.state=s.state;title.textContent=s.title;detail.textContent=availabilityText(s);const fallback=posts.some(p=>p.engine==='reviewed_fallback'),mixed=posts.some(p=>p.engine==='azure_openai');notice.hidden=!fallback&&!['offline','exhausted','unknown'].includes(s.state);notice.textContent=fallback?(mixed?'Some AI responses unavailable · reviewed notes shown for those presenters.':'AI unavailable · reviewed notes shown. These are not a new AI answer.'):s.state==='exhausted'?'AI allowance reached · reviewed notes shown. Ask the crew can retrieve a saved answer; new answers wait for the reset.':s.state==='offline'?'AI unavailable · reviewed notes shown.':'Checking AI availability · reviewed notes remain available.';const connection=document.getElementById('connection-status');if(connection)connection.textContent=s.title;}
aiAvailability.subscribe(update);aiAvailability.check();
document.addEventListener('btr-contributions',e=>{posts=e.detail.posts;update(aiAvailability.get());});
document.addEventListener('btr-ai-finished',()=>aiAvailability.check(true));
document.addEventListener('visibilitychange',()=>{if(!document.hidden)aiAvailability.check();});
setInterval(()=>{if(!document.hidden)aiAvailability.check();},60000);
const kit=el('details','recording-kit');kit.innerHTML='<summary>Recording kit · 110 seconds, with evidence</summary><p>Use the synthetic match route for the recording while generated-footage permissions and kit markings are unresolved. Keep the film’s existing provenance available.</p><ol><li><b>0–20s:</b> Open the synthetic replay. Show the source and one completed pass.</li><li><b>20–40s:</b> Compare a beginner explanation with passing gain in metres; switch to Spanish.</li><li><b>40–65s:</b> Change the tracking record and show the withdrawn claim in the separate overlay.</li><li><b>65–90s:</b> Show an actual successful recovery run and its exported receipts. Confirm AI availability first. If showing saved results, identify them as saved.</li><li><b>90–110s:</b> Generate seed 107, show its consistency checks, and download the event dataset.</li></ol><p><a href="assets/btr-recording-guide.txt" download>Download the recording script ↓</a> · <a href="assets/btr-verification-summary.json" download>Download the verified run summary ↓</a></p><p>The summary records the earlier live check: four model requests before interruption, six total after resume. It is a verification summary, not a raw trace or a fresh run. The revised run used reviewed notes for two rejected AI responses. Record fresh receipts only when a new run actually succeeds.</p><p><a href="assets/btr-footage-register.json" download>Footage provenance and unresolved rights ↓</a></p>';
document.querySelector('.proof-console').append(kit);
